package dev.codex.lastzhelper;
import java.io.*;import java.util.*;import org.json.*;
public final class TruckRawProbe {
 static long field(long t,String k)throws Exception{return StateProbe.ptr(StateProbe.findField(t,k));}
 static JSONArray cargo(long data,String group)throws Exception{JSONArray a=new JSONArray();long goods=field(field(data,group),"cur");for(TruckDiscoveryProbe.Value v:TruckDiscoveryProbe.rows(goods)){if((v.tag&15)!=5)continue;JSONObject o=v.json();JSONArray fields=new JSONArray();for(TruckDiscoveryProbe.Value f:TruckDiscoveryProbe.rows(v.raw)){JSONObject j=f.json();if((f.tag&15)==5&&!f.key.matches("(?i).*(class_type|config|super).*")){JSONArray children=new JSONArray();for(TruckDiscoveryProbe.Value c:TruckDiscoveryProbe.rows(f.raw))children.put(c.json());j.put("fields",children);}fields.put(j);}o.put("fields",fields);a.put(o);}return a;}
 public static void main(String[] args){run(args);}
 static void run(String[] args){try{JSONObject state=StateProbe.snapshot(args[0]);String[] bind=StateProbe.text(args[0]).split(" ");long m=Long.parseLong(bind[2],16);StateProbe.mem=new RandomAccessFile("/proc/"+state.getInt("pid")+"/mem","r");long L=StateProbe.ptr(StateProbe.ptr(m+32)+16),globals=StateProbe.ptr(StateProbe.ptr(StateProbe.ptr(StateProbe.ptr(L+24)+64)+16)+16);long manager=field(field(globals,"DataCenter"),"LWTrainDataManager"),list=field(manager,"enemyTrucks");JSONArray trucks=new JSONArray();for(TruckDiscoveryProbe.Value v:TruckDiscoveryProbe.rows(list)){if((v.tag&15)!=5)continue;JSONObject t=new JSONObject().put("id",Long.toString(StateProbe.number(v.raw,"uuid"))).put("quality",StateProbe.number(v.raw,"quality")).put("power",StateProbe.number(v.raw,"power"));t.put("base",cargo(v.raw,"baseGoods"));t.put("extra",cargo(v.raw,"extraGoods"));trucks.put(t);}JSONArray items=new JSONArray();long itemDic=field(field(field(globals,"DataCenter"),"ItemTemplateManager"),"itemDic");for(TruckDiscoveryProbe.Value v:TruckDiscoveryProbe.rows(itemDic)){if(!v.key.matches("#?(210454|252007|200364|252014|230100|210453|210452)"))continue;JSONObject item=v.json();if((v.tag&15)==5)item.put("fields",TruckDiscoveryProbe.describe(v.raw,2));items.put(item);}System.out.println(new JSONObject().put("ok",true).put("trucks",trucks).put("items",items).toString(2));StateProbe.mem.close();}catch(Throwable e){try{System.out.println(new JSONObject().put("ok",false).put("error",e.toString()).toString(2));}catch(Exception ignored){}System.exit(1);}}
}
